import{_ as a,o as t,c as o,a5 as i}from"./chunks/framework.-jms6n7v.js";const g=JSON.parse(`{"title":"Migration","description":"These guides move an application's data into DaruDB from the embedded database it uses now, one page for each.","frontmatter":{"title":"Migration","order":1,"prev":{"text":"Performance","link":"/performance"},"next":{"text":"SQLite","link":"/migration/sqlite"}},"headers":[{"level":2,"title":"How a move goes","slug":"how-a-move-goes","link":"#how-a-move-goes","children":[]},{"level":2,"title":"Where the copy runs","slug":"where-the-copy-runs","link":"#where-the-copy-runs","children":[]},{"level":2,"title":"Copying fast","slug":"copying-fast","link":"#copying-fast","children":[]},{"level":2,"title":"Guides","slug":"guides","link":"#guides","children":[]}],"relativePath":"migration/index.md","filePath":"en/migration/index.md","lastUpdated":1792917766000}`),s={name:"migration/index.md"};function n(l,e,r,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="migrating-from-another-database" tabindex="-1">Migrating from another database <a class="header-anchor" href="#migrating-from-another-database" aria-label="Permalink to &quot;Migrating from another database&quot;">​</a></h1><p>These guides move an application&#39;s data into DaruDB from the embedded database it uses now, one page for each.</p><p>To change the schema of a DaruDB file instead, see <a href="./../guide/migrations">Migrations</a> in the guide.</p><h2 id="how-a-move-goes" tabindex="-1">How a move goes <a class="header-anchor" href="#how-a-move-goes" aria-label="Permalink to &quot;How a move goes&quot;">​</a></h2><p>Every guide follows the same four steps, and the old file is never changed:</p><ol><li><strong>Declare a schema</strong> that holds what the old database holds: a collection for each table or class, and a field for each column or property. Each guide has a table of what maps to what, and of what has no counterpart yet.</li><li><strong>Copy the data</strong> with code that opens the old file read-only through its own library and writes objects into a new DaruDB file. Copying each record&#39;s key as the object&#39;s key keeps every reference between records valid as a link.</li><li><strong>Check the copy</strong>: compare the number of records in each table or class with the number of objects in each collection, and run the <a href="./../guide/tools#check-a-file">integrity check</a> on the new file.</li><li><strong>Point the application at the new file</strong>, and keep the old one until the application has run on the new one for a while.</li></ol><h2 id="where-the-copy-runs" tabindex="-1">Where the copy runs <a class="header-anchor" href="#where-the-copy-runs" aria-label="Permalink to &quot;Where the copy runs&quot;">​</a></h2><p>A server&#39;s data is in one place, so a script copies it once. An app&#39;s data is on each device, so the copy runs in the app itself, once, at the first launch of the version that moves, before the app opens the old file. The Dart guides show it so: the copy is written under another name, <code>app.darudb.part</code>, and renamed into place once it is closed, so a copy that a crash or a closed app cut short is started again at the next launch, and the old file is deleted only in a later version. Code in any other language is made safe to cut short the same way.</p><h2 id="copying-fast" tabindex="-1">Copying fast <a class="header-anchor" href="#copying-fast" aria-label="Permalink to &quot;Copying fast&quot;">​</a></h2><ul><li><strong>Many objects to a transaction.</strong> The copies write a thousand objects to each write transaction, which costs one commit for the thousand rather than one each.</li><li><strong>Deferred commits, then close.</strong> Each transaction commits without waiting for the disk, and closing the database at the end makes all of them durable at once. A copy that stops halfway, for any reason, leaves a file to delete and copy again, so nothing is lost by not waiting.</li><li><strong>No order to follow.</strong> A link may name an object that is not there yet, so collections can be copied in any order.</li></ul><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><p>The guides of the language chosen in the sidebar:</p><div class="lang-only" data-code-lang="rust"><ul><li><a href="./sqlite">SQLite</a>: tables, rows and indexes, through <code>rusqlite</code>.</li><li><a href="./lmdb">LMDB</a>: named databases of bytes, through <code>heed</code>.</li><li><a href="./redb">redb</a>: typed tables and multimap tables.</li><li><a href="./sled">sled</a>: trees of bytes.</li></ul></div><div class="lang-only" data-code-lang="node"><ul><li><a href="./sqlite">SQLite</a>: tables, rows and indexes, through <code>node:sqlite</code>.</li><li><a href="./realm">Realm</a>: object schemas, links and embedded objects, through <code>realm</code>.</li><li><a href="./lmdb">LMDB</a>: named databases, through <code>lmdb</code>.</li><li><a href="./level">LevelDB</a>: sublevels of JSON values, through <code>classic-level</code>.</li></ul></div><div class="lang-only" data-code-lang="dart"><ul><li><a href="./sqlite">SQLite</a>: tables, rows and indexes, through <code>sqflite</code>, inside a Flutter app.</li><li><a href="./realm">Realm</a>: object schemas, links and embedded objects, through <code>realm</code>, inside a Flutter app.</li><li><a href="./hive">Hive</a>: boxes and type adapters, through <code>hive_ce</code>, inside a Flutter app.</li></ul></div><div class="lang-only" data-code-lang="python"><ul><li><a href="./sqlite">SQLite</a>: tables, rows and indexes, through <code>sqlite3</code>.</li><li><a href="./lmdb">LMDB</a>: named databases of bytes, through <code>lmdb</code>.</li><li><a href="./tinydb">TinyDB</a>: tables of JSON documents.</li><li><a href="./shelve">shelve</a>: a shelf of pickled values.</li></ul></div>',16)])])}const p=a(s,[["render",n]]);export{g as __pageData,p as default};
